import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, HEARTBEAT_STALE_MS, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

class HttpError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
    readonly fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  const text = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(text),
    'cache-control': 'no-store',
  });
  res.end(text);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  send(res, err.status, { error });
}

function invalid(fields: FieldError[]): HttpError {
  return new HttpError(400, 'invalid_request', 'The request is invalid.', fields);
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => {
      if (tooLarge) reject(invalid([{ field: 'body', message: 'Request body is too large.' }]));
      else resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function validatePayload(value: unknown): Payload {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw invalid([{ field: 'body', message: 'Body must be a JSON object.' }]);
  }
  const obj = value as Record<string, unknown>;
  const fields: FieldError[] = [];
  for (const key of Object.keys(obj)) {
    if (key !== 'input' && key !== 'steps' && key !== 'failAttempts') {
      fields.push({ field: key, message: 'Unknown field.' });
    }
  }
  const input = obj.input;
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'input is required.' });
  } else if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input must be a string.' });
  } else if (input.length < 1 || input.length > 1000) {
    fields.push({ field: 'input', message: 'input must be 1 to 1000 characters long.' });
  } else if (input.trim().length === 0) {
    fields.push({ field: 'input', message: 'input must not be only whitespace.' });
  }
  const intField = (name: 'steps' | 'failAttempts', min: number, max: number, def: number): number => {
    if (!Object.hasOwn(obj, name)) return def;
    const v = obj[name];
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
      return def;
    }
    return v;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);
  if (fields.length > 0) throw invalid(fields);
  return { input: input as string, steps, failAttempts };
}

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(`
  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                    idempotency_key, payload, run_after, created_at, updated_at)
  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)
`);
const selectHeartbeat = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawKey = req.headers['idempotency-key'];
  const key = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
  const body = await readBody(req);

  if (key !== undefined && !KEY_RE.test(key)) {
    throw invalid([{ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' }]);
  }
  const contentType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (contentType !== 'application/json') {
    throw invalid([{ field: 'body', message: 'Content-Type must be application/json.' }]);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(body);
  } catch {
    throw invalid([{ field: 'body', message: 'Body must be valid JSON.' }]);
  }
  const payload = validatePayload(parsed);
  const payloadText = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);

  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = selectByKey.get(key) as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.payload === payloadText) return send(res, 200, toJob(existing));
        throw new HttpError(409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    insertJob.run(id, payload.input, payload.steps, payload.failAttempts, key ?? null, payloadText, now, now);
    db.exec('COMMIT');
    send(res, 201, toJob(selectById.get(id) as JobRow));
  } catch (err) {
    if (db.isTransaction) db.exec('ROLLBACK');
    throw err;
  }
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const allow = (methods: string[]) => {
    if (!methods.includes(method)) {
      res.setHeader('allow', methods.join(', '));
      throw new HttpError(405, 'method_not_allowed', `Method ${method} is not allowed on ${pathname}.`);
    }
  };

  if (pathname === '/' || pathname === '/index.html') {
    allow(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    allow(['GET']);
    const hb = selectHeartbeat.get() as { at: number } | undefined;
    const up = hb !== undefined && Date.now() - hb.at < HEARTBEAT_STALE_MS;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    allow(['GET', 'POST']);
    if (method === 'POST') return createJob(req, res);
    const rows = selectAll.all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    allow(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      id = m[1]!;
    }
    const row = selectById.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', `Job ${id} was not found.`);
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', `No route for ${pathname}.`);
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

